#!/usr/bin/env node
// tests/bench/run.js — generated-code performance benchmark (todos/0186).
//
// Measures the speed of code GENERATED by compiler.js on a CPU-bound vendor
// workload (the headless SameBoy GBC core), slope-based so V8 tier-up and
// process startup cancel, with a framebuffer-checksum correctness interlock
// so a miscompile can never masquerade as "faster".
//
// This is an INFORMATIONAL, OPT-IN harness — deliberately not a tests/run.js
// gating suite: the ROM input is gitignored (copyrighted), so a fresh
// checkout or CI must never depend on it. Missing inputs SKIP (exit 0):
//   - no ROM  → whole bench skips with an explicit message
//   - no clang-simplified checkout → cc-only run, clang legs noted skipped
//
// Usage:
//   node tests/bench/run.js [--rom=PATH] [--clang=PATH] [--reps=N] [--skip-build]
//     --rom=PATH    GB/GBC ROM (default: vendor/gameboy/roms/SuperMarioDeluxe.gbc,
//                   else first *.gbc/*.gb found there)
//     --clang=PATH  cc2wasm driver for the comparison build
//                   (default probe: ~/git/clang-simplified/cc2wasm)
//     --reps=N      wall-time repetitions per frame count, best-of (default 3)
//     --skip-build  reuse build/bench/*.wasm from a previous run
//
// Exit codes: 0 = ran (or skipped for missing optional input), 1 = FAIL
// (checksum mismatch vs reps / clang / committed baseline, or build error).

'use strict';
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execFileSync } = require('child_process');

const ROOT = path.resolve(__dirname, '..', '..');
const HOST = path.join(ROOT, 'host.js');
const OUT_DIR = path.join(ROOT, 'build', 'bench');
const SB = path.join(ROOT, 'vendor', 'sameboy');
const BASELINES = path.join(__dirname, 'baselines.json');

const FRAME_NS = [200, 600, 1000]; // slope over first..last cancels tier-up
const SB_SRCS = [
  'core/apu.c', 'core/camera.c', 'core/display.c', 'core/gb.c',
  'core/joypad.c', 'core/mbc.c', 'core/memory.c', 'core/printer.c',
  'core/random.c', 'core/rumble.c', 'core/sgb.c', 'core/sm83_cpu.c',
  'core/timing.c', 'core/workboy.c', 'src/bootroms.c',
].map(p => path.join(SB, p));
const SB_DEFS = [
  '-DGB_INTERNAL', '-DGB_DISABLE_DEBUGGER', '-DGB_DISABLE_CHEATS',
  '-DGB_DISABLE_CHEAT_SEARCH', '-DGB_DISABLE_REWIND', '-DGB_DISABLE_TIMEKEEPING',
];

// ---------- args ----------
const args = {};
for (const a of process.argv.slice(2)) {
  const m = /^--([^=]+)(?:=(.*))?$/.exec(a);
  if (!m) { console.error(`unknown arg: ${a}`); process.exit(2); }
  args[m[1]] = m[2] === undefined ? true : m[2];
}
const REPS = args.reps ? Math.max(1, parseInt(args.reps, 10)) : 3;

// ---------- optional inputs ----------
function findRom() {
  if (args.rom) {
    if (fs.existsSync(args.rom)) return path.resolve(args.rom);
    console.error(`--rom=${args.rom}: not found`);
    process.exit(2);
  }
  const dir = path.join(ROOT, 'vendor', 'gameboy', 'roms');
  const preferred = path.join(dir, 'SuperMarioDeluxe.gbc');
  if (fs.existsSync(preferred)) return preferred;
  if (fs.existsSync(dir)) {
    const any = fs.readdirSync(dir).filter(f => /\.gbc?$/i.test(f)).sort();
    if (any.length) return path.join(dir, any[0]);
  }
  return null;
}
function findClang() {
  if (args.clang) {
    if (fs.existsSync(args.clang)) return path.resolve(args.clang);
    console.error(`--clang=${args.clang}: not found`);
    process.exit(2);
  }
  const probe = path.join(process.env.HOME || '', 'git', 'clang-simplified', 'cc2wasm');
  return fs.existsSync(probe) ? probe : null;
}

const rom = findRom();
if (!rom) {
  console.log('bench: SKIP — no GB/GBC ROM found (vendor/gameboy/roms/ is empty; '
    + 'drop one there or pass --rom=PATH — see tests/bench/README.md)');
  process.exit(0);
}
const clang = findClang();

// ---------- build ----------
fs.mkdirSync(OUT_DIR, { recursive: true });
const ccWasm = path.join(OUT_DIR, 'sameboy_cc.wasm');
const clWasm = path.join(OUT_DIR, 'sameboy_clang.wasm');
const benchC = path.join(__dirname, 'sameboy_bench.c');
const incs = ['-I' + path.join(SB, 'core'), '-I' + path.join(SB, 'src')];

if (!args['skip-build'] || !fs.existsSync(ccWasm)) {
  console.log('bench: building sameboy with compiler.js ...');
  execFileSync('node', [path.join(ROOT, 'compiler.js'), '-o', ccWasm,
    ...incs, '--allow-zero-length-arrays', ...SB_DEFS, benchC, ...SB_SRCS],
    { stdio: 'inherit' });
}
let haveClang = false;
if (clang && (!args['skip-build'] || !fs.existsSync(clWasm))) {
  console.log('bench: building sameboy with clang (cc2wasm) ...');
  try {
    execFileSync(clang, [benchC, ...SB_SRCS, ...incs, ...SB_DEFS, '-o', clWasm],
      { stdio: 'inherit', cwd: path.dirname(clang) });
    haveClang = true;
  } catch (e) {
    console.log('bench: clang build failed — continuing cc-only');
  }
} else if (clang) {
  haveClang = fs.existsSync(clWasm);
}
if (!clang) console.log('bench: no cc2wasm found — clang comparison skipped');

// ---------- deterministic proxy: static wasm stats (cc build only) ----------
// A fail-loud MVP(+sign-ext, +0xFC) instruction counter. If compiler.js ever
// emits an opcode this table doesn't know, we report and drop the proxy
// rather than print a silently-wrong count.
function wasmStats(file) {
  const b = fs.readFileSync(file);
  let i = 8;
  const u = () => { let r = 0, s = 0, byte; do { byte = b[i++]; r |= (byte & 0x7f) << s; s += 7; } while (byte & 0x80); return r >>> 0; };
  const sk = () => { let byte; do { byte = b[i++]; } while (byte & 0x80); }; // skip any LEB (32/64)
  let codeSize = 0, instrs = 0;
  const NO_IMM = op => (op >= 0x45 && op <= 0xc4) || op === 0x00 || op === 0x01
    || op === 0x05 || op === 0x0b || op === 0x0f || op === 0x1a || op === 0x1b || op === 0xd1;
  while (i < b.length) {
    const id = b[i++]; const sz = u(); const end = i + sz;
    if (id !== 10) { i = end; continue; }
    codeSize = sz;
    const nfun = u();
    for (let f = 0; f < nfun; f++) {
      const bodyEnd = (() => { const bs = u(); return i + bs; })();
      const ng = u();
      for (let g = 0; g < ng; g++) { u(); i++; } // local groups: count + valtype
      while (i < bodyEnd) {
        const op = b[i++]; instrs++;
        if (NO_IMM(op)) continue;
        else if (op === 0x02 || op === 0x03 || op === 0x04) sk(); // blocktype
        else if (op === 0x0c || op === 0x0d || op === 0x10 || (op >= 0x20 && op <= 0x26) || op === 0xd2) u();
        else if (op === 0x0e) { const n = u(); for (let z = 0; z <= n; z++) u(); }
        else if (op === 0x11) { u(); u(); }
        else if (op >= 0x28 && op <= 0x3e) { u(); u(); } // memarg
        else if (op === 0x3f || op === 0x40) i++;
        else if (op === 0x41 || op === 0x42) sk();
        else if (op === 0x43) i += 4;
        else if (op === 0x44) i += 8;
        else if (op === 0xd0) i++;
        else if (op === 0x1c) { const n = u(); i += n; }
        else if (op === 0xfc) {
          const sub = u();
          if (sub <= 7) { /* nontrapping float→int: no imm */ }
          else if (sub === 8) { u(); i++; }        // memory.init
          else if (sub === 9 || sub === 13) u();   // data.drop / elem.drop
          else if (sub === 10) { i += 2; }         // memory.copy
          else if (sub === 11) i++;                // memory.fill
          else if (sub === 12 || sub === 14) { u(); u(); } // table.init/copy
          else if (sub >= 15 && sub <= 17) u();    // table.grow/size/fill
          else throw new Error(`unknown 0xfc subop ${sub}`);
        } else throw new Error(`unknown opcode 0x${op.toString(16)} at ${i - 1}`);
      }
      if (i !== bodyEnd) throw new Error(`func ${f}: body decode overran (${i} != ${bodyEnd})`);
    }
    i = end;
  }
  return { bytes: b.length, codeSize, instrs };
}
let ccStats = null;
try { ccStats = wasmStats(ccWasm); }
catch (e) { console.log(`bench: static op-count proxy unavailable (${e.message})`); }

// ---------- timed runs + checksum interlock ----------
function runOnce(wasm, frames) {
  const t0 = Date.now();
  const out = execFileSync('node', [HOST, wasm, rom, String(frames)],
    { encoding: 'utf8', stdio: ['ignore', 'pipe', 'inherit'] });
  const ms = Date.now() - t0;
  const m = /done sum=([0-9a-f]{8})/.exec(out);
  if (!m) throw new Error(`no checksum in output of ${path.basename(wasm)} N=${frames}:\n${out}`);
  return { ms, sum: m[1] };
}

let failed = false;
function fail(msg) { console.error(`bench: FAIL — ${msg}`); failed = true; }

function measure(name, wasm) {
  const res = {}; // N -> {ms, sum}
  for (const N of FRAME_NS) {
    let best = Infinity, sum = null;
    for (let t = 0; t < REPS; t++) {
      const r = runOnce(wasm, N);
      best = Math.min(best, r.ms);
      if (sum === null) sum = r.sum;
      else if (sum !== r.sum) fail(`${name} N=${N}: nondeterministic checksum (${sum} vs ${r.sum})`);
    }
    res[N] = { ms: best, sum };
    console.log(`  ${name} N=${N}: ${best}ms  sum=${sum}`);
  }
  const lo = FRAME_NS[0], hi = FRAME_NS[FRAME_NS.length - 1];
  res.perFrame = (res[hi].ms - res[lo].ms) / (hi - lo);
  return res;
}

const romSha = crypto.createHash('sha256').update(fs.readFileSync(rom)).digest('hex');
const romName = path.basename(rom);
console.log(`bench: sameboy workload, rom=${romName} (sha256 ${romSha.slice(0, 12)}…), reps=${REPS}`);

const cc = measure('compiler.js', ccWasm);
const cl = haveClang ? measure('clang', clWasm) : null;

// cc vs clang: same program, same input → same framebuffer, or a miscompile.
if (cl) for (const N of FRAME_NS) {
  if (cc[N].sum !== cl[N].sum)
    fail(`N=${N}: cc sum ${cc[N].sum} != clang sum ${cl[N].sum} — MISCOMPILE, timing numbers are void`);
}

// committed baseline (keyed by ROM sha256): the cross-run interlock.
let baselines = {};
if (fs.existsSync(BASELINES)) baselines = JSON.parse(fs.readFileSync(BASELINES, 'utf8'));
const base = baselines[romSha];
if (base) {
  for (const N of FRAME_NS) {
    if (base.sums[N] && base.sums[N] !== cc[N].sum)
      fail(`N=${N}: sum ${cc[N].sum} != baseline ${base.sums[N]} (${base.name}) — MISCOMPILE`);
  }
} else {
  console.log(`bench: note — no committed baseline for this ROM; add to tests/bench/baselines.json:`);
  console.log(`  ${JSON.stringify({ [romSha]: { name: romName, sums: Object.fromEntries(FRAME_NS.map(N => [N, cc[N].sum])) } })}`);
}

// ---------- the one-line result ----------
const sumState = failed ? 'sum FAIL' : (base || cl) ? 'sum OK' : 'sum unbaselined';
const parts = [`BENCH sameboy(${romName})`, `cc ${cc.perFrame.toFixed(3)} ms/frame`];
if (cl) parts.push(`clang ${cl.perFrame.toFixed(3)} ms/frame`, `${(cc.perFrame / cl.perFrame).toFixed(2)}x`);
else parts.push('clang skipped');
parts.push(sumState);
if (ccStats) parts.push(`${ccStats.bytes} B wasm, ${ccStats.instrs} instrs (code ${ccStats.codeSize} B)`);
console.log(parts.join(' | '));
process.exit(failed ? 1 : 0);
